  PRIMARY KEY (`id`) USING BTREE
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci ROW_FORMAT=DYNAMIC;


DROP TABLE IF EXISTS `v_checkins`;
CREATE ALGORITHM=UNDEFINED DEFINER=`myadmin`@`localhost` SQL SECURITY DEFINER VIEW `v_checkins` AS select `checkins`.`id` AS `id`,`checkins`.`user_id` AS `user_id`,`checkins`.`display_name` AS `display_name`,`checkins`.`place_name` AS `place_name`,`checkins`.`latitude` AS `latitude`,`checkins`.`longitude` AS `longitude`,`checkins`.`checkin_time` AS `checkin_time`,`checkins`.`photo_path` AS `photo_path`,`checkins`.`check_type` AS `check_type`,`checkins`.`token_checkin` AS `token_checkin`,`checkins`.`remark` AS `remark`,`ims_employee_line_user`.`line_picture_profile` AS `line_picture_profile`,`ims_employee_line_user`.`emp_name` AS `emp_name` from (`checkins` left join `ims_employee_line_user` on((`ims_employee_line_user`.`line_user_id` = `checkins`.`user_id`)));


DROP TABLE IF EXISTS `v_checkins_time`;
CREATE ALGORITHM=UNDEFINED DEFINER=`myadmin`@`localhost` SQL SECURITY DEFINER VIEW `v_checkins_time` AS with `ranked_checkins` as (select `c`.`id` AS `id`,`c`.`user_id` AS `user_id`,`c`.`display_name` AS `display_name`,`c`.`place_name` AS `place_name`,`c`.`latitude` AS `latitude`,`c`.`longitude` AS `longitude`,`c`.`checkin_time` AS `checkin_time`,`c`.`photo_path` AS `photo_path`,`c`.`check_type` AS `check_type`,`c`.`token_checkin` AS `token_checkin`,`c`.`remark` AS `remark`,`e`.`line_picture_profile` AS `line_picture_profile`,`e`.`emp_name` AS `emp_name`,cast(`c`.`checkin_time` as date) AS `checkin_date`,row_number() OVER (PARTITION BY `c`.`user_id`,cast(`c`.`checkin_time` as date) ORDER BY `c`.`checkin_time` )  AS `rn_asc`,row_number() OVER (PARTITION BY `c`.`user_id`,cast(`c`.`checkin_time` as date) ORDER BY `c`.`checkin_time` desc )  AS `rn_desc` from (`checkins` `c` left join `ims_employee_line_user` `e` on((`e`.`line_user_id` = `c`.`user_id`)))) select `ranked_checkins`.`id` AS `id`,`ranked_checkins`.`user_id` AS `user_id`,`ranked_checkins`.`display_name` AS `display_name`,`ranked_checkins`.`place_name` AS `place_name`,`ranked_checkins`.`latitude` AS `latitude`,`ranked_checkins`.`longitude` AS `longitude`,`ranked_checkins`.`checkin_time` AS `checkin_time`,`ranked_checkins`.`photo_path` AS `photo_path`,`ranked_checkins`.`check_type` AS `check_type`,`ranked_checkins`.`token_checkin` AS `token_checkin`,`ranked_checkins`.`remark` AS `remark`,`ranked_checkins`.`line_picture_profile` AS `line_picture_profile`,`ranked_checkins`.`emp_name` AS `emp_name`,`ranked_checkins`.`checkin_date` AS `checkin_date`,`ranked_checkins`.`rn_asc` AS `rn_asc`,`ranked_checkins`.`rn_desc` AS `rn_desc` from `ranked_checkins` where ((`ranked_checkins`.`rn_asc` = 1) or (`ranked_checkins`.`rn_desc` = 1)) order by `ranked_checkins`.`id` desc;


DROP TABLE IF EXISTS `v_i_payment_voucher`;
CREATE ALGORITHM=UNDEFINED DEFINER=`myadmin`@`localhost` SQL SECURITY DEFINER VIEW `v_i_payment_voucher` AS select `ims_payment_voucher`.`id` AS `id`,`ims_payment_voucher`.`doc_no` AS `doc_no`,`ims_payment_voucher`.`doc_date` AS `doc_date`,substr(`ims_payment_voucher`.`doc_date`,1,2) AS `doc_day`,`ims_payment_voucher`.`doc_month` AS `doc_month`,`ims_payment_voucher`.`doc_year` AS `doc_year`,`ims_payment_voucher`.`doc_runno` AS `doc_runno`,`ims_payment_voucher`.`requester` AS `requester`,`ims_payment_voucher`.`supplier_id` AS `supplier_id`,`ims_payment_voucher`.`supplier_name` AS `supplier_name`,`ims_payment_voucher`.`purpose` AS `purpose`,`ims_payment_voucher`.`payment_method` AS `payment_method`,`ims_payment_voucher`.`bank_no` AS `bank_no`,`ims_payment_voucher`.`total_amount` AS `total_amount`,`ims_payment_voucher`.`picture_doc` AS `picture_doc`,`ims_payment_voucher`.`create_name` AS `create_name`,`ims_payment_voucher`.`checker_name` AS `checker_name`,`ims_payment_voucher`.`approve_name` AS `approve_name`,`ims_payment_voucher`.`receipt_name` AS `receipt_name`,`ims_payment_voucher`.`approve_status` AS `approve_status`,`ims_payment_voucher`.`status` AS `status`,`ims_payment_voucher`.`create_date` AS `create_date`,`ims_payment_voucher`.`update_date` AS `update_date`,`ims_payment_voucher`.`remark` AS `remark` from `ims_payment_voucher`;


DROP TABLE IF EXISTS `v_ims_expenses`;
CREATE ALGORITHM=UNDEFINED DEFINER=`myadmin`@`localhost` SQL SECURITY DEFINER VIEW `v_ims_expenses` AS select `ims_expenses`.`id` AS `id`,`ims_expenses`.`runno` AS `runno`,`ims_expenses`.`doc_id` AS `doc_id`,`ims_expenses`.`expense_date` AS `expense_date`,`ims_expenses`.`exp_month` AS `exp_month`,`ims_expenses`.`exp_year` AS `exp_year`,`ims_expenses`.`inv` AS `inv`,`ims_expenses`.`category_id` AS `category_id`,`ims_category`.`category_name` AS `category_name`,`ims_expenses`.`description` AS `description`,`ims_expenses`.`qty` AS `qty`,`ims_expenses`.`amount` AS `amount`,`ims_expenses`.`remark` AS `remark`,`ims_expenses`.`created_at` AS `created_at`,`ims_expenses`.`updated_at` AS `updated_at`,`ims_expenses`.`unit_id` AS `unit_id`,`ims_unit`.`unit_name` AS `unit_name`,`ims_expenses`.`approve_status` AS `approve_status`,`ims_month`.`month_name` AS `month_name`,`ims_expenses`.`file_attach` AS `file_attach`,`ims_expenses`.`receipt_name` AS `receipt_name`,`ims_expenses`.`payment_method` AS `payment_method`,`ims_expenses`.`price_per_unit` AS `price_per_unit`,`ims_expenses`.`total_amount` AS `total_amount`,`ims_expenses`.`doc_ref` AS `doc_ref` from (((`ims_expenses` left join `ims_category` on((`ims_expenses`.`category_id` = `ims_category`.`category_id`))) left join `ims_unit` on((`ims_expenses`.`unit_id` = `ims_unit`.`unit_id`))) left join `ims_month` on((`ims_expenses`.`exp_month` = `ims_month`.`month_id`)));


DROP TABLE IF EXISTS `v_ims_house`;
CREATE ALGORITHM=UNDEFINED DEFINER=`myadmin`@`localhost` SQL SECURITY DEFINER VIEW `v_ims_house` AS select `ims_house`.`id` AS `id`,`ims_house`.`house_number` AS `house_number`,`ims_house`.`contact_name` AS `contact_name`,`ims_house`.`phone_number` AS `phone_number`,`ims_house`.`alley` AS `alley`,`ims_house`.`remark` AS `remark`,`ims_house`.`status` AS `status`,`ims_house`.`picture` AS `picture`,`ims_house`.`car_no1` AS `car_no1`,`ims_house`.`car_no2` AS `car_no2`,`ims_house`.`car_no3` AS `car_no3`,`ims_house`.`car_no4` AS `car_no4`,`ims_house`.`car_no5` AS `car_no5`,`ims_house`.`house_status` AS `house_status`,`ims_house_line_user`.`line_user_id` AS `line_user_id`,`ims_house_line_user`.`line_user_name` AS `line_user_name`,`ims_house_line_user`.`line_picture_profile` AS `line_picture_profile`,`m_house_master`.`area_size` AS `area_size`,`m_house_master`.`garbage_collection_fee` AS `garbage_collection_fee`,`m_house_master`.`common_fee` AS `common_fee` from ((`ims_house` left join `ims_house_line_user` on(((`ims_house_line_user`.`house_number` = `ims_house`.`house_number`) and (`ims_house_line_user`.`line_phone` = `ims_house`.`phone_number`)))) left join `ims_house_master` `m_house_master` on((`m_house_master`.`house_number` = `ims_house`.`house_number`)));


DROP TABLE IF EXISTS `v_ims_house_meeting`;
CREATE ALGORITHM=UNDEFINED DEFINER=`myadmin`@`localhost` SQL SECURITY DEFINER VIEW `v_ims_house_meeting` AS select `ims_house_meeting`.`id` AS `id`,`ims_house_meeting`.`house_number` AS `house_number`,`ims_house_meeting`.`meeting_year` AS `meeting_year`,`ims_house_meeting`.`meeting_date` AS `meeting_date`,`ims_house_meeting`.`meeting_name` AS `meeting_name`,`ims_house_meeting`.`attendance_name` AS `attendance_name`,`ims_house_meeting`.`meeting_status` AS `meeting_status`,`ims_house_meeting`.`discount_value` AS `discount_value`,`ims_house_meeting`.`remark` AS `remark`,`ims_house_meeting`.`status` AS `status`,`ims_house_master`.`alley` AS `alley`,`ims_house_master`.`area_size` AS `area_size`,`ims_house_master`.`common_fee` AS `common_fee` from (`ims_house_meeting` left join `ims_house_master` on((`ims_house_master`.`house_number` = `ims_house_meeting`.`house_number`)));


DROP TABLE IF EXISTS `v_ims_house_payment_date`;
CREATE ALGORITHM=UNDEFINED DEFINER=`myadmin`@`localhost` SQL SECURITY DEFINER VIEW `v_ims_house_payment_date` AS select `ims_house_payment`.`payment_date` AS `payment_date`,date_format(str_to_date(`ims_house_payment`.`payment_date`,'%d-%m-%Y'),'%Y-%m-%d') AS `payment_date_start`,date_format(str_to_date(`ims_house_payment`.`payment_date`,'%d-%m-%Y'),'%Y-%m-%d') AS `payment_date_end`,sum(cast(`ims_house_payment`.`amount` as unsigned)) AS `total_amount`,str_to_date(`ims_house_payment`.`payment_date`,'%d-%m-%Y') AS `payment_date_id` from `ims_house_payment` group by `ims_house_payment`.`payment_date`;


DROP TABLE IF EXISTS `v_ims_installment`;
CREATE ALGORITHM=UNDEFINED DEFINER=`myadmin`@`localhost` SQL SECURITY DEFINER VIEW `v_ims_installment` AS select `ims_installment`.`id` AS `id`,`ims_installment`.`installment_id` AS `installment_id`,`ims_installment`.`house_number` AS `house_number`,`ims_installment`.`doc_date` AS `doc_date`,`ims_installment`.`debtor` AS `debtor`,`ims_installment`.`detail` AS `detail`,`ims_installment`.`principal_amount` AS `principal_amount`,`ims_installment`.`down_payment` AS `down_payment`,`ims_installment`.`principal_amount_balance` AS `principal_amount_balance`,`ims_installment`.`num_installments` AS `num_installments`,`ims_installment`.`installment_per_period` AS `installment_per_period`,`ims_installment`.`interest_rate` AS `interest_rate`,`ims_installment`.`installment_img` AS `installment_img`,`ims_installment`.`start_date` AS `start_date`,`ims_installment`.`status` AS `status`,`ims_installment`.`create_date` AS `create_date`,`ims_installment`.`update_date` AS `update_date`,`ims_installment`.`payment_due_day_period` AS `payment_due_day_period`,substr(`ims_installment`.`doc_date`,4,2) AS `doc_month`,substr(`ims_installment`.`doc_date`,7,4) AS `doc_year` from `ims_installment`;


DROP TABLE IF EXISTS `v_ims_installment_detail`;
