DROP TABLE IF EXISTS `v_ims_inventory`;
CREATE ALGORITHM=UNDEFINED DEFINER=`myadmin`@`localhost` SQL SECURITY DEFINER VIEW `v_ims_inventory` AS select `ims_inventory`.`id` AS `id`,`ims_inventory`.`doc_no` AS `doc_no`,`ims_inventory`.`doc_year` AS `doc_year`,`ims_inventory`.`doc_runno` AS `doc_runno`,`ims_inventory`.`supplier_id` AS `supplier_id`,`ims_inventory`.`doc_date` AS `doc_date`,`ims_inventory`.`status` AS `status`,`ims_inventory`.`create_date` AS `create_date`,`ims_inventory`.`update_date` AS `update_date`,`ims_supplier`.`supplier_name` AS `supplier_name`,`ims_inventory`.`total_amount` AS `total_amount`,`ims_inventory`.`purpose` AS `purpose`,`ims_inventory`.`transaction_type` AS `transaction_type`,`ims_inventory`.`file_attach` AS `file_attach` from (`ims_inventory` left join `ims_supplier` on((`ims_supplier`.`supplier_id` = `ims_inventory`.`supplier_id`)));


DROP TABLE IF EXISTS `v_ims_inventory_detail`;
CREATE ALGORITHM=UNDEFINED DEFINER=`myadmin`@`localhost` SQL SECURITY DEFINER VIEW `v_ims_inventory_detail` AS select `ims_inventory_detail`.`id` AS `id`,`ims_inventory_detail`.`doc_no` AS `doc_no`,`ims_inventory_detail`.`doc_date` AS `doc_date`,`ims_inventory_detail`.`line_no` AS `line_no`,`ims_inventory_detail`.`transaction_type` AS `transaction_type`,`ims_inventory_detail`.`product_id` AS `product_id`,`ims_inventory_detail`.`product_name` AS `product_name`,`ims_inventory_detail`.`unit_id` AS `unit_id`,`ims_inventory_detail`.`unit_name` AS `unit_name`,`ims_inventory_detail`.`quantity` AS `quantity`,(case when (`ims_inventory_detail`.`transaction_type` = '+') then `ims_inventory_detail`.`quantity` when (`ims_inventory_detail`.`transaction_type` = '-') then -(`ims_inventory_detail`.`quantity`) else 0 end) AS `signed_quantity`,`ims_inventory_detail`.`price` AS `price`,`ims_inventory_detail`.`total_price` AS `total_price`,`ims_inventory_detail`.`create_date` AS `create_date`,`ims_inventory_detail`.`update_date` AS `update_date` from `ims_inventory_detail`;


